import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Get","description":"","frontmatter":{},"headers":[{"level":1,"title":"Get","slug":"get"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBuf/Get.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBuf/Get.md"}'),l={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TBuf/Get.md"};function p(i,t,o,r,d,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="get" tabindex="-1">Get <a class="header-anchor" href="#get" aria-label="Permalink to &quot;Get&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>从TBuf上获取指定长度的Tensor，或者获取全部长度的Tensor。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>获取全部长度的Tensor</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline LocalTensor&lt;T&gt; Get()</span></span></code></pre></div></li><li><p>获取指定长度的Tensor</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline LocalTensor&lt;T&gt; Get(uint32_t len)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>待获取Tensor的数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>len</td><td>输入</td><td>需要获取的Tensor元素个数。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>len的数值是Tensor中元素的个数，len*sizeof(T)不能超过TBuf初始化时的长度。</p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>获取到的<a href="./../../../../基础数据结构/LocalTensor/LocalTensor.html">LocalTensor</a>。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 为TBuf初始化分配内存，分配内存长度为1024字节</span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TBuf&lt;AscendC::TPosition::VECCALC&gt; calcBuf; // 模板参数为TPosition中的VECCALC类型</span></span>
<span class="line"><span>uint32_t byteLen = 1024;</span></span>
<span class="line"><span>pipe.InitBuffer(calcBuf, byteLen);</span></span>
<span class="line"><span>// 从calcBuf获取Tensor,Tensor为pipe分配的所有内存大小，为1024字节</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;int32_t&gt; tempTensor1 = calcBuf.Get&lt;int32_t&gt;();</span></span>
<span class="line"><span>// 从calcBuf获取Tensor,Tensor为128个int32_t类型元素的内存大小，为512字节</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;int32_t&gt; tempTensor2 = calcBuf.Get&lt;int32_t&gt;(128);</span></span></code></pre></div><p>对同一个TBuf对象连续调用Get接口，获取到的Tensor首地址是相同的，不会依次向后偏移。如果需要获取偏移之后的Tensor，可以使用如下方法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>// 模板参数为TPosition中的VECCALC类型</span></span>
<span class="line"><span>AscendC::TBuf&lt;AscendC::TPosition::VECCALC&gt; calcBuf; </span></span>
<span class="line"><span>// 分配一个2048字节的连续空间</span></span>
<span class="line"><span>uint32_t byteLen = 2048;</span></span>
<span class="line"><span>pipe.InitBuffer(calcBuf, byteLen);</span></span>
<span class="line"><span>// 从calcBuf获取tensor1，tensor1为pipe分配的所有内存大小，为2048字节</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;int32_t&gt; tensor1 = calcBuf.Get&lt;int32_t&gt;();</span></span>
<span class="line"><span>// 用户指定tensor1的第256个int32_t的偏移位置为tensor2的首地址，实际上tensor2可以使用的内存大小为1024字节，两个tensor首地址相差256 * sizeof(int32_t)字节</span></span>
<span class="line"><span>auto tensor2 = tensor1[256];</span></span></code></pre></div>`,20)])])}const b=a(l,[["render",p]]);export{u as __pageData,b as default};
